import {models} from './models.js';
import {APP_VERSION,EQUATION_VERSION,evaluate,totals,importRows} from './inventory-core.js';
import {csvEncode,csvParse,xlsxWrite,xlsxRead,download} from './io.js';
const $=id=>document.getElementById(id),KEY='pfi-inventories-v1',DRAFT='pfi-current-v1';let rows=[],id=crypto.randomUUID(),savedAt=null,page=0;
const fields=['survey-name','survey-date','observer','compartment','plot'];const fmt=(v,n=2)=>v.toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n});
const message=(text,bad=false)=>{$('inventory-message').textContent=text;$('inventory-message').className=bad?'error':'notice';};
const meta=()=>Object.fromEntries(fields.map(f=>[f,$(f).value]));
const snapshot=()=>({schema:1,id,appVersion:APP_VERSION,equationVersion:EQUATION_VERSION,metadata:meta(),rows,savedAt:new Date().toISOString()});
function library(){const x=JSON.parse(localStorage.getItem(KEY)||'{}');if(!x||Array.isArray(x)||typeof x!=='object')throw Error('Saved inventory list is damaged. Download a backup of the current inventory.');return x;}
function listSaved(){try{$('saved-inventories').replaceChildren(new Option('Select a saved inventory',''));for(const [key,item] of Object.entries(library()))$('saved-inventories').add(new Option(`${item.metadata?.['survey-name']||'Untitled'} · ${item.rows?.length||0} trees · ${item.savedAt?.slice(0,10)||''}`,key));}catch(e){$('save-status').textContent=e.message;}}
function save(){try{const data=snapshot(),all=library();all[id]=data;localStorage.setItem(KEY,JSON.stringify(all));localStorage.setItem(DRAFT,id);savedAt=data.savedAt;$('save-status').textContent=`Saved on this device at ${new Date(savedAt).toLocaleTimeString()}. Export a backup for safekeeping; there is no cloud sync.`;listSaved();return true;}catch(e){$('save-status').textContent='Could not save on this device. Download a backup now. '+e.message;return false;}}
function validate(data){if(data?.schema!==1||data.equationVersion!==EQUATION_VERSION||!Array.isArray(data.rows)||data.rows.length>1000||!data.metadata||typeof data.metadata!=='object')throw Error('Unsupported backup format or equation version.');const clean={metadata:{},rows:[]};for(const f of fields)clean.metadata[f]=String(data.metadata[f]??'').slice(0,150);for(const r of data.rows){if(!r||typeof r!=='object')throw Error('Invalid tree record.');clean.rows.push({tree_id:String(r.tree_id??'').slice(0,200),model_id:String(r.model_id??''),dbh:String(r.dbh??''),unit:String(r.unit??''),notes:String(r.notes??'').slice(0,1000)});}return clean;}
function open(data,copy=false){const clean=validate(data);id=copy?crypto.randomUUID():data.id||crypto.randomUUID();rows=clean.rows;page=0;for(const f of fields)$(f).value=clean.metadata[f];render();save();}
function view(inventory){$('inventory-view').hidden=!inventory;$('single-view').hidden=inventory;$('single-tab').setAttribute('aria-pressed',String(!inventory));$('inventory-tab').setAttribute('aria-pressed',String(inventory));}
$('single-tab').onclick=()=>view(false);$('inventory-tab').onclick=()=>view(true);
function nextId(){let n=rows.length+1;while(rows.some(r=>r.tree_id===String(n)))n++;return String(n);}
function add(current=false){if(rows.length>=1000){message('Limit: 1,000 trees per inventory.',true);return;}rows.push({tree_id:nextId(),model_id:$('species').value,dbh:current?$('diameter').value:'',unit:$('unit').value,notes:''});page=Math.floor((rows.length-1)/50);render();save();}
$('add-row').onclick=()=>add();$('use-current').onclick=()=>add(true);$('save-inventory').onclick=()=>save();
$('previous-page').onclick=()=>{page--;render()};$('next-page').onclick=()=>{page++;render()};
function render(){const evaluated=evaluate(rows),t=totals(evaluated);page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(rows.length/50)-1)));$('previous-page').disabled=page===0;$('next-page').disabled=(page+1)*50>=rows.length;$('page-status').textContent=rows.length?`Rows ${page*50+1}–${Math.min((page+1)*50,rows.length)} of ${rows.length}`:'No rows';$('included-count').textContent=t.count;$('excluded-count').textContent=t.excluded;$('total-label').textContent=t.excluded?'Partial total · valid trees only':'Total volume · under bark';$('inventory-cft').textContent=fmt(t.cft);$('inventory-m3').textContent=fmt(t.m3,3);$('empty-inventory').hidden=rows.length>0;const body=$('tree-rows');body.replaceChildren();for(const [j,r] of evaluated.slice(page*50,(page+1)*50).entries()){const i=page*50+j;const tr=document.createElement('tr');if(r.error)tr.className='invalid-row';function cell(){const td=document.createElement('td');tr.append(td);return td;}function control(key,type='input'){const td=cell(),el=document.createElement(type);el.setAttribute('aria-label',`${key} for row ${i+1}`);if(type==='input'){el.value=r[key];el.maxLength=key==='notes'?1000:200;if(key==='dbh'){el.inputMode='decimal';el.type='number';el.step='any';}}else if(key==='model_id'){if(!models.some(m=>m.id===r.model_id))el.add(new Option('Unknown table: '+r.model_id,r.model_id));for(const m of models)el.add(new Option(`${m.id} · ${m.division} · ${m.forest} · ${m.species}`,m.id));el.value=r.model_id;}else{for(const v of ['in','cm'])el.add(new Option(v,v));if(!['in','cm'].includes(r.unit))el.add(new Option(r.unit||'Select unit',r.unit));el.value=r.unit;}el.onchange=()=>{rows[i][key]=el.value;render();save();};td.append(el);}control('tree_id');control('model_id','select');control('dbh');control('unit','select');cell().textContent=r.result?fmt(r.result.cubicFeet):'—';cell().textContent=r.error||'Included';control('notes');const del=document.createElement('button');del.textContent='Remove';del.setAttribute('aria-label','Remove tree '+(r.tree_id||i+1));del.onclick=()=>{rows.splice(i,1);render();save();};cell().append(del);body.append(tr);}
$('species-summary').replaceChildren();if(t.count){const p=document.createElement('p');p.textContent='Species totals — '+Object.entries(t.groups).map(([s,g])=>`${s}: ${g.count} trees, ${fmt(g.cft)} ft³`).join(' · ');$('species-summary').append(p);}}
for(const f of fields)$(f).addEventListener('change',save);
$('new-inventory').onclick=()=>{if(!save()&&!confirm('Saving failed. Start a new inventory anyway? Download a backup first to keep the current records.'))return;id=crypto.randomUUID();rows=[];for(const f of fields)$(f).value='';$('survey-date').value=new Date().toLocaleDateString('en-CA');render();save();};
$('load-inventory').onclick=()=>{const key=$('saved-inventories').value;if(!key)return;try{const target=library()[key];if(!save())throw Error('Save or back up your current work before opening another inventory.');open(target);message('Saved inventory opened.');}catch(e){message(e.message,true);}};
const headers=['tree_id','model_id','dbh','unit','notes'];
$('template-csv').onclick=()=>download(new Blob([csvEncode([headers])],{type:'text/csv;charset=utf-8'}),'PFI_tree_import_template.csv');
$('template-xlsx').onclick=()=>download(xlsxWrite([{name:'Trees',rows:[headers]},{name:'Available tables',rows:[['model_id','region','division','location','species','minimum_dbh_in','maximum_dbh_in'],...models.map(m=>[m.id,m.region,m.division,m.forest,m.species,...m.range])]},{name:'Instructions',rows:[['PFI tree import template'],['One tree per row in Trees. Enter tree_id, model_id, dbh and unit (in or cm).'],['Select model_id from Available tables. Use unique tree IDs.'],['Enter numbers as values, not formulas. Maximum 1,000 trees.'],['Import appends rows to the current inventory. Invalid rows remain visible and are excluded from totals.']]}]),'PFI_tree_import_template.xlsx');
$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Import file must be under 5 MB.');const grid=file.name.toLowerCase().endsWith('.xlsx')?await xlsxRead(await file.arrayBuffer()):csvParse(await file.text());const incoming=importRows(grid);if(!incoming.length)throw Error('No tree rows found.');if(rows.length+incoming.length>1000)throw Error('Inventory would exceed 1,000 trees.');rows.push(...incoming);render();save();message(`${incoming.length} rows imported. Review excluded rows before using the total.`);}catch(err){message(err.message,true);}finally{e.target.value='';}};
const filename=()=>($('survey-name').value||'PFI_inventory').replace(/[^a-zA-Z0-9_-]/g,'_').slice(0,80);
function output(){const ev=evaluate(rows),t=totals(ev),md=meta();const treeRows=[['tree_id','model_id','dbh','unit','notes','region','division','location','species','height_ft','volume_ft3','volume_m3','status','warning','bark_basis','app_version','equation_version','inventory_name','survey_date','observer','compartment','plot'],...ev.map(r=>[r.tree_id,r.model_id,r.result?Number(r.dbh):r.dbh,r.unit,r.notes,r.model?.region||'',r.model?.division||'',r.model?.forest||'',r.model?.species||'',r.result?.heightFeet??'',r.result?.cubicFeet??'',r.result?.cubicMetres??'',r.result?'Included':'Excluded',r.error,'Under bark',APP_VERSION,EQUATION_VERSION,md['survey-name'],md['survey-date'],md.observer,md.compartment,md.plot])];return {ev,t,md,treeRows};}
$('export-csv').onclick=()=>{download(new Blob([csvEncode(output().treeRows)],{type:'text/csv;charset=utf-8'}),filename()+'.csv');message('CSV exported. It includes every tree and its status; excluded rows have no volume.');};
$('export-xlsx').onclick=()=>{const o=output();download(xlsxWrite([{name:'Trees',rows:o.treeRows},{name:'Summary',rows:[['PFI inventory summary'],['Inventory',o.md['survey-name']],['Survey date',o.md['survey-date']],['Observer',o.md.observer],['Compartment',o.md.compartment],['Plot',o.md.plot],['Included trees',o.t.count],['Excluded rows',o.t.excluded],['Total type',o.t.excluded?'Partial: valid trees only':'All recorded trees'],['Volume ft3',o.t.cft],['Volume m3',o.t.m3],['Bark basis','Under bark'],['App version',APP_VERSION],['Equation version',EQUATION_VERSION],['Exported',new Date().toISOString()],[],['Species','Included trees','Volume ft3','Volume m3'],...Object.entries(o.t.groups).map(([s,g])=>[s,g.count,g.cft,g.m3])]}]),filename()+'.xlsx');message('Excel exported with Trees and Summary sheets.');};
$('export-backup').onclick=()=>download(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'}),filename()+'_backup.json');
$('restore-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Backup is too large.');const data=JSON.parse(await file.text());validate(data);if(!save())throw Error('Back up the current inventory before restoring another.');open(data,true);message('Backup restored as a separate inventory.');}catch(err){message(err.message,true);}finally{e.target.value='';}};
function report(){const {ev,t,md}=output(),target=$('print-report');target.replaceChildren();function p(text,tag='p'){const el=document.createElement(tag);el.textContent=text;target.append(el);return el;}p('Field inventory report','h1');p(`${md['survey-name']||'Untitled inventory'} · ${md['survey-date']||'Date not recorded'}`);p(`Observer: ${md.observer||'—'} | Compartment: ${md.compartment||'—'} | Plot: ${md.plot||'—'}`);p(`${t.excluded?'PARTIAL TOTAL — VALID TREES ONLY':'TOTAL'}: ${fmt(t.cft)} ft³ / ${fmt(t.m3,3)} m³. Included: ${t.count}. Excluded: ${t.excluded}. Under bark.`);p(`Calculator ${APP_VERSION} · Equation set ${EQUATION_VERSION} · Printed ${new Date().toLocaleString()}`);const table=document.createElement('table');const head=document.createElement('thead'),hr=document.createElement('tr');for(const text of ['Tree','Location / table','DBH','Height ft','Volume ft³','Volume m³','Status / notes']){const th=document.createElement('th');th.textContent=text;hr.append(th);}head.append(hr);table.append(head);const body=document.createElement('tbody');for(const r of ev){const tr=document.createElement('tr');for(const text of [r.tree_id,`${r.model?.division||''} · ${r.model?.forest||''} · ${r.model?.species||''} (${r.model_id})`,`${r.dbh} ${r.unit}`,r.result?fmt(r.result.heightFeet):'—',r.result?fmt(r.result.cubicFeet):'—',r.result?fmt(r.result.cubicMetres,3):'—',(r.error||'Included')+(r.notes?' / '+r.notes:'')]){const td=document.createElement('td');td.textContent=text;tr.append(td);}body.append(tr);}table.append(body);target.append(table);for(const [s,g] of Object.entries(t.groups))p(`${s}: ${g.count} trees · ${fmt(g.cft)} ft³ · ${fmt(g.m3,3)} m³`);p('Totals sum unrounded valid estimates. Displayed row rounding can differ from the rounded total. No per-hectare expansion has been applied.');document.body.dataset.print='inventory';window.print();}
$('print-inventory').onclick=report;window.addEventListener('afterprint',()=>delete document.body.dataset.print);
try{listSaved();const key=localStorage.getItem(DRAFT),data=key&&library()[key];if(data)open(data);else{$('survey-date').value=new Date().toLocaleDateString('en-CA');render();}}catch(e){render();$('save-status').textContent='Could not restore saved data. '+e.message;}
